SELECT EXISTS(
    SELECT 1
    FROM auth_user_agreement_acceptance
    WHERE user_id = #{userId}
      AND agreement_type = 'PARENT_USER_AGREEMENT'
      AND agreement_version = #{agreementVersion}
)

